"""Small non-blocking Win32 popups used by tray actions."""
import ctypes
from ctypes import wintypes
import threading


user32 = ctypes.windll.user32
kernel32 = ctypes.windll.kernel32
gdi32 = ctypes.windll.gdi32
user32.CreateWindowExW.restype = wintypes.HWND
user32.CreateWindowExW.argtypes = [
    wintypes.DWORD, wintypes.LPCWSTR, wintypes.LPCWSTR, wintypes.DWORD,
    ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int,
    wintypes.HWND, wintypes.HMENU, wintypes.HINSTANCE, wintypes.LPVOID,
]
user32.LoadCursorW.restype = wintypes.HANDLE
kernel32.GetModuleHandleW.restype = wintypes.HMODULE
gdi32.CreateFontW.restype = wintypes.HANDLE

WM_COMMAND = 0x0111
WM_CLOSE = 0x0010
WM_DESTROY = 0x0002
WM_SETFONT = 0x0030
WM_TIMER = 0x0113
WS_CHILD = 0x40000000
WS_VISIBLE = 0x10000000
WS_POPUP = 0x80000000
WS_CAPTION = 0x00C00000
WS_SYSMENU = 0x00080000
BS_PUSHBUTTON = 0
SS_LEFT = 0
WS_EX_TOPMOST = 0x00000008
WS_EX_TOOLWINDOW = 0x00000080
SW_SHOWNORMAL = 1
SW_SHOWNOACTIVATE = 4
SPI_GETWORKAREA = 0x0030
COLOR_WINDOW = 5

LRESULT = ctypes.c_ssize_t
WNDPROC = ctypes.WINFUNCTYPE(LRESULT, wintypes.HWND, wintypes.UINT,
                            wintypes.WPARAM, wintypes.LPARAM)
user32.DefWindowProcW.restype = LRESULT
user32.DefWindowProcW.argtypes = [
    wintypes.HWND, wintypes.UINT, wintypes.WPARAM, wintypes.LPARAM]
user32.SendMessageW.restype = LRESULT
user32.SendMessageW.argtypes = [
    wintypes.HWND, wintypes.UINT, wintypes.WPARAM, wintypes.LPARAM]
user32.PostMessageW.argtypes = [
    wintypes.HWND, wintypes.UINT, wintypes.WPARAM, wintypes.LPARAM]


class WNDCLASSW(ctypes.Structure):
    _fields_ = [
        ("style", wintypes.UINT), ("lpfnWndProc", WNDPROC),
        ("cbClsExtra", ctypes.c_int), ("cbWndExtra", ctypes.c_int),
        ("hInstance", wintypes.HINSTANCE), ("hIcon", wintypes.HICON),
        ("hCursor", wintypes.HANDLE), ("hbrBackground", wintypes.HBRUSH),
        ("lpszMenuName", wintypes.LPCWSTR), ("lpszClassName", wintypes.LPCWSTR),
    ]


class PopupHandle:
    def __init__(self):
        self._ready = threading.Event()
        self._closed = threading.Event()
        self._window = None
        self._text = None
        self._selected = None

    def _attach(self, window, text):
        self._window, self._text = window, text
        self._ready.set()

    def update(self, message):
        if self._ready.wait(2) and self._text:
            user32.SetWindowTextW(self._text, str(message))

    def close(self):
        if self._ready.wait(2) and self._window:
            user32.PostMessageW(self._window, WM_CLOSE, 0, 0)

    def wait_choice(self):
        self._closed.wait()
        return self._selected


_CLASS = "EXPCWLKTrayPopup"
_registered = False
_registration_lock = threading.Lock()
_states = {}


def _run_callback(callback):
    if callback:
        threading.Thread(target=callback, daemon=True, name="popup-action").start()


@WNDPROC
def _window_proc(hwnd, message, wparam, lparam):
    state = _states.get(hwnd)
    if message == WM_COMMAND and state:
        button_id = int(wparam) & 0xffff
        if button_id in state["callbacks"]:
            callback = state["callbacks"][button_id]
            state["handle"]._selected = button_id - 100
            user32.DestroyWindow(hwnd)
            _run_callback(callback)
            return 0
    if message == WM_TIMER:
        user32.DestroyWindow(hwnd)
        return 0
    if message == WM_CLOSE:
        user32.DestroyWindow(hwnd)
        return 0
    if message == WM_DESTROY:
        state = _states.pop(hwnd, None)
        if state:
            state["handle"]._closed.set()
        user32.PostQuitMessage(0)
        return 0
    return user32.DefWindowProcW(hwnd, message, wparam, lparam)


def _register_class():
    global _registered
    with _registration_lock:
        if _registered:
            return
        instance = kernel32.GetModuleHandleW(None)
        window_class = WNDCLASSW()
        window_class.lpfnWndProc = _window_proc
        window_class.hInstance = instance
        window_class.hCursor = user32.LoadCursorW(None, ctypes.c_void_p(32512))
        window_class.hbrBackground = ctypes.c_void_p(COLOR_WINDOW + 1)
        window_class.lpszClassName = _CLASS
        atom = user32.RegisterClassW(ctypes.byref(window_class))
        if not atom and ctypes.get_last_error() != 1410:
            raise ctypes.WinError(ctypes.get_last_error())
        _registered = True


def _popup_thread(handle, message, timeout, buttons):
    _register_class()
    instance = kernel32.GetModuleHandleW(None)
    actionable = bool(buttons)
    line_count = str(message).count("\n") + 1
    expanded = ((actionable and any(len(label) > 14 for label, _ in buttons)) or
                line_count > 3)
    if expanded:
        width = 540
        height = min(390, 82 + line_count * 20 + (45 if actionable else 0))
    else:
        width, height = (390, 150) if actionable else (360, 112)
    work = wintypes.RECT()
    user32.SystemParametersInfoW(SPI_GETWORKAREA, 0, ctypes.byref(work), 0)
    x, y = work.right - width - 16, work.bottom - height - 16
    hwnd = user32.CreateWindowExW(
        WS_EX_TOPMOST | WS_EX_TOOLWINDOW, _CLASS, "EXPC-WLK",
        WS_POPUP | WS_CAPTION | WS_SYSMENU | WS_VISIBLE,
        x, y, width, height, None, None, instance, None,
    )
    if not hwnd:
        handle._ready.set()
        handle._closed.set()
        return
    text_height = height - (100 if actionable else 38) if expanded else (58 if actionable else 54)
    text = user32.CreateWindowExW(
        0, "STATIC", str(message), WS_CHILD | WS_VISIBLE | SS_LEFT,
        16, 14, width - 38, text_height, hwnd, None, instance, None,
    )
    font = gdi32.CreateFontW(-16, 0, 0, 0, 400, 0, 0, 0, 1, 0, 0, 5, 0, "Segoe UI")
    user32.SendMessageW(text, WM_SETFONT, font, 1)
    callbacks = {}
    if actionable:
        button_width = 180 if expanded else 105
        total = len(buttons) * button_width + max(0, len(buttons) - 1) * 10
        left = width - total - 20
        for index, (label, callback) in enumerate(buttons, start=100):
            button = user32.CreateWindowExW(
                0, "BUTTON", label, WS_CHILD | WS_VISIBLE | BS_PUSHBUTTON,
                left, height - 68 if expanded else 82, button_width, 30,
                hwnd, ctypes.c_void_p(index), instance, None,
            )
            user32.SendMessageW(button, WM_SETFONT, font, 1)
            callbacks[index] = callback
            left += button_width + 10
    _states[hwnd] = {"callbacks": callbacks, "font": font, "handle": handle}
    handle._attach(hwnd, text)
    if timeout:
        user32.SetTimer(hwnd, 1, int(timeout * 1000), None)
    user32.ShowWindow(hwnd, SW_SHOWNORMAL if actionable else SW_SHOWNOACTIVATE)
    user32.UpdateWindow(hwnd)
    message_data = wintypes.MSG()
    while user32.GetMessageW(ctypes.byref(message_data), None, 0, 0) > 0:
        user32.TranslateMessage(ctypes.byref(message_data))
        user32.DispatchMessageW(ctypes.byref(message_data))
    gdi32.DeleteObject(font)


def show(message, timeout=5, buttons=None):
    """Show a bottom-right popup and return a thread-safe update handle."""
    handle = PopupHandle()
    def run():
        try:
            _popup_thread(handle, message, timeout, buttons or [])
        finally:
            handle._ready.set()
            handle._closed.set()
    threading.Thread(
        target=run, daemon=True, name="tray-popup",
    ).start()
    return handle


def choose(message, labels):
    """Show an action popup and synchronously return the selected button index."""
    handle = show(message, timeout=None, buttons=[(label, None) for label in labels])
    return handle.wait_choice()
